    for c in range(w):
        if len(set(g[r][c] for r in range(h)))==1 and g[0][c]!=7: bc=c
    if bc is None:
        for r in range(h):
            if len(set(g[r]))==1 and g[r][0]!=7: bc=r  # horizontal bar index
            else: break
    out=[row[:] for row in g]
    # find bar orientation
    vert = any(len(set(g[r][c] for r in range(h)))==1 and g[0][c]!=7 for c in range(w))
    pts=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (7,4) or (vert and g[r][c]!=g[0][0])]
