        for y,x,_ in pts:
            out[y][bc]=_
            # stem toward bar
            cc=x; step=1 if x<bc else -1
            while abs(cc-bc)<6 and cc!=bc:
                d=abs(cc-bc)
                if d%2==0: out[y][cc]=_
                cc+=step
        return out
    else:
        br=[r for r in range(h) if all(g[r][c]==0 for c in range(w))][0]
        pc=[p[1] for p in pts]
        for c in range(max(0,min(pc)-1),min(w,max(pc)+2)):
            for r in range(br-1,br+2):
