def f(inp):
    H=len(inp);W=len(inp[0])
    bcol=max(set(sum(inp,[])),key=lambda x:sum(row.count(x) for row in inp))
    bars=[r for r in range(H) if sum(1 for c in range(W) if inp[r][c]==bcol)==W]
    pts=[(r,c) for r in range(H) for c in range(W) if inp[r][c] not in (bcol,) and inp[r][c]!=0]
    pcolor=inp[pts[0][0]][pts[0][1]]
    out=[row[:] for row in inp]
    for pr,pc in pts:
        above=[b for b in bars if b<pr]; below=[b for b in bars if b>pr]
        far=(max(above,key=lambda b:pr-b)) if above else None
        flb=min(below,key=lambda b:b-pr) if below else None
        # 3x3 rings at each adjacent bar on point column; center cell overwritten by beam later? check: center = point color
        for br in [far,flb]:
            if br is None: continue
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    rr,cc=br+dr,pc+dc
